from pathlib import Path

base=Path("_scratch/s11c")
def rows(run,prefix):
    return [dict(s.split('=',1) for s in line.split() if '=' in s)
            for line in (base/run/"stdout").read_text().splitlines() if line.startswith(prefix)]

ref=rows("open_reservoir_aperture_reference_b","modes=192 ")
for prep in ("rest48","rest128"):
    for r,f in zip(ref,rows("open_reservoir_"+prep,"tone=")):
        delta=100*(float(f["power_per_b2"])/float(r["wall"])-1)
        partition=100*(float(f["feed_fraction"])-float(r["feed_fraction"]))
        print(f"mesh={prep} omega={r['omega']} power_bias_pct={delta:.12g} feed_fraction_bias_points={partition:.12g}")
